<?php $payload = ClientApi::data($api->request('GET','api/notifications?page=1&per_page=50')); $rows = is_array($payload['items'] ?? null) ? $payload['items'] : []; ?>
<section class="panel"><h2 class="section-title">Toutes vos notifications</h2><?php if (!$rows): ?><div class="empty"><div class="empty-icon">♧</div><h3>Aucune notification pour le moment</h3><p>Les confirmations et informations importantes apparaîtront ici.</p></div><?php else: ?><div class="list"><?php foreach ($rows as $n): ?><article class="list-row"><div><div class="row-title"><?= client_h($n['titre'] ?? '') ?> <?php if (empty($n['lu_at'])): ?><span class="badge pending">Non lue</span><?php endif; ?></div><div><?= nl2br(client_h($n['contenu'] ?? '')) ?></div><div class="row-meta"><?= client_h(client_format_date($n['created_at'] ?? null)) ?></div></div><?php if (empty($n['lu_at'])): ?><form method="post"><?= client_csrf_field() ?><input type="hidden" name="action" value="notification_read"><input type="hidden" name="id" value="<?= (int)$n['id'] ?>"><button class="btn btn-outline" type="submit">Marquer comme lue</button></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section>
